 openPanel('KETEF HINNOM · JERUSALEM, ISRAEL','<article class="investigation-reader"><h2>A blessing on silver</h2><p>Two tiny silver amulets, late seventh or early sixth century BC. Their wording includes the blessing preserved in Numbers 6:24–26.'+BD_INVESTIGATION.marker('ketef',1)+'</p>'+board+'<details class="note-block"><summary>The discovery</summary><p>Junior-high volunteers joined Gabriel Barkay’s 1979 excavation. One boy, Nathan, brought attention to a repository beneath a burial bench. Specialists later conserved and read the silver.'+BD_INVESTIGATION.marker('ketef',3)+'</p></details><p class="fine-print">This is a digital image exercise. Fragile originals require professional conservation; you are not unrolling an ancient object.</p></article>','investigation-ketef');
 for(const b of document.querySelectorAll('[data-silver-tile],[data-silver-slot]'))b.addEventListener('click',function chooseOrPlace(){if(this.hasAttribute('data-silver-slot')&&Number.isInteger(BD_INVESTIGATION.selected)){BD_INVESTIGATION.place(Number(this.dataset.silverSlot));return;}if(this.hasAttribute('data-silver-value')){BD_INVESTIGATION.selected=Number(this.dataset.silverValue);for(const tile of document.querySelectorAll('.silver-tile'))tile.classList.toggle('selected',tile===this);$('#silver-feedback').textContent='Section '+['C','A','D','B'][BD_INVESTIGATION.selected]+' selected. Choose its space.';}/* Code by Daniel using ChatGPT November 20, 2026 */});
