 const silverHost=$('.silver-board');if(silverHost)silverHost.addEventListener('pointermove',function carrySilverImage(){const ghost=$('.tile-ghost'),tile=silverHost.querySelector('[data-silver-value="'+BD_INVESTIGATION.selected+'"]');if(ghost&&tile){ghost.classList.add('silver-carry');ghost.style.backgroundImage=tile.style.backgroundImage;ghost.style.backgroundPosition=tile.style.backgroundPosition;}/* Code by Daniel using ChatGPT November 20, 2026 */});
 for(const b of document.querySelectorAll('[data-silver-answer]'))b.addEventListener('click',function drawConclusion(){if(this.dataset.silverAnswer!=='blessing'){$('#silver-feedback').textContent=this.dataset.silverAnswer==='whole-book'?'The amulets date this wording. Dating a whole biblical book takes a wider argument.':'The silver predates Jesus by centuries. Compare the wording with Numbers 6.';return;}s.earned=true;persist();BD_INVESTIGATION.ketefCard();game.dirty=true;/* Code by Daniel using ChatGPT November 20, 2026 */});
 /* Code by Daniel using ChatGPT November 20, 2026 */
