 const oldAbout=showAbout;showAbout=function howTheStudyWorks(){oldAbout();$('#panel-body').insertAdjacentHTML('beforeend','<section class="note-block"><h3>How this game works</h3><p>You work with study reproductions and original paintings. Light highlights and image joins teach observation; they are not instrument scans or documentary photographs. Original artifacts remain with their collections. Conservation of fragile originals belongs to trained specialists.</p><p>Michael Grisanti begins with confidence in God’s Word and shows how discoveries can confirm its history. We follow that approach: read Scripture, investigate the people and places it names, and consider the whole historical case for Jesus. God uses truthful reasons and the witness of his Word to persuade and strengthen us. His Spirit upholds our faith.</p><button class="button secondary" data-investigation="bibliography">Read the source trail</button></section>'+BD_LIBRARY.translationNotices(true));/* Code by Daniel using ChatGPT November 20, 2026 */};
