 document.addEventListener('click',function investigationActions(e){const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.source){const [id,n]=b.dataset.source.split(':');BD_INVESTIGATION.sources(id,Number(n));return;}const a=b.dataset.investigation;if(!a)return;const actions={intro:BD_INVESTIGATION.intro,avaris:BD_INVESTIGATION.avaris,ketef:BD_INVESTIGATION.ketef,fraction:BD_INVESTIGATION.fraction,bibliography:BD_INVESTIGATION.bibliography};if(actions[a])actions[a]();if(a==='room')BD_MUSEUM.enter('investigation',{arrival:[160,805]});if(a==='source-back')BD_PAD.back();if(a==='fraction-next'){BD_INVESTIGATION.state().fraction=Math.min(5,BD_INVESTIGATION.state().fraction+1);persist();BD_INVESTIGATION.fraction();}if(a==='silver-help'){const s=BD_INVESTIGATION.state(),i=[0,1,2,3].find(function mismatch(n){return s.order[n]!==n;/* Code by Daniel using ChatGPT November 20, 2026 */});if(i!==undefined){BD_INVESTIGATION.selected=i;BD_INVESTIGATION.place(i);}}/* Code by Daniel using ChatGPT November 20, 2026 */});
